/**
 * Public API models. They are aliases of the types generated by openapi-typescript
 * from shared/contracts/campaign-api.openapi.yaml (`npm run gen:types`).
 * If the contract changes, regenerate api.generated.ts and the compiler flags every drift.
 */
import type { components } from './api.generated';

export type Campaign = components['schemas']['Campaign'];
export type CampaignStatus = components['schemas']['CampaignStatus'];
export type CreateCampaign = components['schemas']['CreateCampaign'];
export type UpdateCampaign = components['schemas']['UpdateCampaign'];
export type CampaignReport = components['schemas']['CampaignReport'];
export type Problem = components['schemas']['Problem'];

export interface CampaignPage {
  items: Campaign[];
  page: number;
  pageSize: number;
  total: number;
}

export const CAMPAIGN_STATUSES: readonly CampaignStatus[] = ['DRAFT', 'ACTIVE', 'PAUSED', 'EXHAUSTED'];
